package com.mytransitgps.modules.ciq.collector;
import com.mytransitgps.modules.ciq.client.LtaTrafficIncidentsClient;import com.mytransitgps.modules.ciq.config.CiqProperties;import com.mytransitgps.modules.ciq.domain.TrafficIncidentRecord;import com.mytransitgps.modules.ciq.parser.TrafficIncidentsParser;import com.mytransitgps.modules.ciq.persistence.*;import com.mytransitgps.modules.ciq.quality.TrafficIncidentsValidator;import com.mytransitgps.modules.ciq.storage.*;import com.mytransitgps.platform.collection.*;import org.slf4j.*;
/** API03 独立 Collector。 */
public class CiqTrafficIncidentsCollector implements DataCollector {private static final Logger log=LoggerFactory.getLogger(CiqTrafficIncidentsCollector.class);private final CiqPagedJsonCollectorSupport<TrafficIncidentRecord> support;public CiqTrafficIncidentsCollector(LtaTrafficIncidentsClient client,CiqProperties p,CiqJsonStorageService storage,TrafficIncidentsParser parser,TrafficIncidentsValidator validator,TrafficIncidentsPersistenceService persistence,CiqAuditPersistenceService audit){support=new CiqPagedJsonCollectorSupport<>("API03",CiqApiCode.API03,CollectorCode.CIQ_TRAFFIC_INCIDENTS,client,p,p.getCollectors().getTrafficIncidents(),storage,parser::parse,validator::isValid,persistence==null?null:persistence::persist,audit,log);}public ModuleCode moduleCode(){return ModuleCode.CIQ;}public CollectorCode collectorCode(){return CollectorCode.CIQ_TRAFFIC_INCIDENTS;}public CollectionResult collect(CollectionContext c){return support.collect(c);}}
